CREATE TABLE IF NOT EXISTS units (id INTEGER PRIMARY KEY AUTOINCREMENT, unit_code VARCHAR(50) UNIQUE NOT NULL, title VARCHAR(255) NOT NULL, category VARCHAR(100) NOT NULL, beds INTEGER NOT NULL, baths INTEGER NOT NULL, monthly_rate DECIMAL(10,2) NOT NULL, daily_rate DECIMAL(10,2) NOT NULL, status VARCHAR(50) DEFAULT 'available', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
